// Parse the AI response to extract JSON
let aiResponse = $('OpenAI Chat Model').first().json.text || '';

// Try to extract JSON from the response
let parsedData = {};
try {
  // Look for JSON in the response
  const jsonMatch = aiResponse.match(/\{[^}]*\}/);
  if (jsonMatch) {
    parsedData = JSON.parse(jsonMatch[0]);
  }
} catch (error) {
  console.log('Error parsing AI response:', error);
}

const validDepartments = [
  "headTable", "technical", "prHr", "design", "rAndD", "contentAndMedia",
  "marketing", "logisticsAndOperations", "communication", "videography",
  "innovation", "sponsorship", "creativity", "offstage"
];
const validDesignations = ["lead", "colead", "associate", "president", "vicePresident", "secretary"];

let department = parsedData.department ? parsedData.department.toLowerCase() : "";
let designation = parsedData.designation ? parsedData.designation.toLowerCase() : "";

// Department mapping for common aliases
const departmentMap = {
  "tech": "technical",
  "pr": "prHr",
  "hr": "prHr",
  "rnd": "rAndD",
  "content": "contentAndMedia",
  "media": "contentAndMedia",
  "logistics": "logisticsAndOperations",
  "operations": "logisticsAndOperations",
  "video": "videography"
};

// If no department specified but designation is executive, assume headTable
if (!department && ["president", "vicepresident", "secretary"].includes(designation)) {
  department = "headTable";
}

// Apply department mapping
department = departmentMap[department] || department;

// Validate department and designation
if (!validDepartments.includes(department)) {
  department = "";
}
if (!validDesignations.includes(designation)) {
  designation = "";
}

return { department, designation };

// Get all input items from both Firestore queries
const items = $input.all();

if (!items || items.length === 0) {
  return { chatResponse: 'No matching users found.' };
}

// Format the response
const formattedUsers = items.map(item => {
  const data = item.json;
  return `${data.name || 'N/A'}, ${data.email || 'N/A'}, ${data.phone_number || 'N/A'}`;
}).join('\n');

return { chatResponse: formattedUsers };
